{"files":[{"path":"index.html","old_sha256":"90bb8e4d256957b32f67f2a142e058d6d63391c8e468784d3b64f8ce6161dbae","content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Calculator</title>
<style>
  body { font-family: Arial, sans-serif; display: flex; justify-content: center; padding: 20px; background: #f0f0f0; }
  .calculator { background: #222; padding: 16px; border-radius: 10px; width: 280px; box-shadow: 0 4px 12px rgba(0,0,0,.3); }
  #display { width: 100%; box-sizing: border-box; font-size: 24px; padding: 10px; text-align: right; border: none; border-radius: 6px; margin-bottom: 12px; background: #fff; }
  .row { display: flex; gap: 8px; margin-bottom: 8px; }
  .row button { flex: 1; font-size: 20px; padding: 14px 0; border: none; border-radius: 6px; background: #444; color: #fff; cursor: pointer; }
  .row button:hover { background: #555; }
  .row button.op { background: #666; }
  .row button.op:hover { background: #777; }
  .row button.clear { background: #c0392b; flex: 3; }
  .row button.clear:hover { background: #d35446; }
</style>
</head>
<body>
<div class="calculator">
  <div class="row"><input id="display" type="text" readonly value="0"></div>
  <div class="row">
    <button data-val="7">7</button>
    <button data-val="8">8</button>
    <button data-val="9">9</button>
    <button data-val="+" class="op">+</button>
  </div>
  <div class="row">
    <button data-val="4">4</button>
    <button data-val="5">5</button>
    <button data-val="6">6</button>
    <button data-val="-" class="op">-</button>
  </div>
  <div class="row">
    <button data-val="1">1</button>
    <button data-val="2">2</button>
    <button data-val="3">3</button>
    <button data-val="*" class="op">*</button>
  </div>
  <div class="row">
    <button data-val="0">0</button>
    <button data-val="." class="op">.</button>
    <button data-val="/" class="op">/</button>
    <button data-val="=" class="op">=</button>
  </div>
  <div class="row">
    <button class="clear" id="clear">Clear</button>
    <button class="op" id="sqrt">√</button>
    <button class="op" id="square">^2</button>
    <button class="op" id="reciprocal">1/x</button>
    <button class="op" id="pi">π</button>
    <button class="op" id="sin">sin</button>
  </div>
</div>
<script>
  const display = document.getElementById('display');
  let expr = '';

  function updateDisplay() {
    display.value = expr === '' ? '0' : expr;
  }

  function calculate() {
    try {
      if (expr === '') throw new Error('empty');
      const result = Function('"use strict"; return (' + expr + ')')();
      if (result === undefined || result === null || isNaN(result)) throw new Error('undefined');
      expr = String(result);
    } catch (e) {
      expr = 'Error';
    }
    updateDisplay();
  }

  function sqrtCalc() {
    try {
      const val = parseFloat(display.value);
      if (isNaN(val)) throw new Error('nan');
      const result = Math.sqrt(val);
      if (isNaN(result)) throw new Error('nan');
      expr = String(result);
    } catch (e) {
      expr = 'Error';
    }
    updateDisplay();
  }

  function squareCalc() {
    try {
      const val = parseFloat(display.value);
      if (isNaN(val)) throw new Error('nan');
      const result = val * val;
      if (isNaN(result)) throw new Error('nan');
      expr = String(result);
    } catch (e) {
      expr = 'Error';
    }
    updateDisplay();
  }

  function reciprocalCalc() {
    try {
      const val = parseFloat(display.value);
      if (isNaN(val) || val === 0) throw new Error('nan');
      const result = 1 / val;
      if (isNaN(result)) throw new Error('nan');
      expr = String(result);
    } catch (e) {
      expr = 'Error';
    }
    updateDisplay();
  }

  function sinCalc() {
    try {
      const val = parseFloat(display.value);
      if (isNaN(val)) throw new Error('nan');
      const result = Math.sin(val);
      if (isNaN(result)) throw new Error('nan');
      expr = String(result);
    } catch (e) {
      expr = 'Error';
    }
    updateDisplay();
  }

  function piCalc() {
    expr = String(Math.PI);
    updateDisplay();
  }

  function press(val) {
    if (expr === 'Error') expr = '';
    if (val === '=') { calculate(); return; }
    expr += val;
    updateDisplay();
  }

  document.querySelectorAll('.row button[data-val]').forEach(btn => {
    btn.addEventListener('click', () => press(btn.getAttribute('data-val')));
  });

  document.getElementById('clear').addEventListener('click', () => {
    expr = '';
    updateDisplay();
  });

  document.getElementById('sqrt').addEventListener('click', sqrtCalc);
  document.getElementById('square').addEventListener('click', squareCalc);
  document.getElementById('reciprocal').addEventListener('click', reciprocalCalc);
  document.getElementById('sin').addEventListener('click', sinCalc);
  document.getElementById('pi').addEventListener('click', piCalc);

  updateDisplay();
</script>
</body>
</html>
"}]}
